--- extract.mjs ---
import fs from 'fs';
import path from 'path';

const dir = 'site';
const files = fs.readdirSync(dir).filter(f => f.endsWith('.html'));

function decodeHref(href) {
  let f = href.split('#')[0].split('?')[0];
  try { f = decodeURIComponent(f); } catch {}
  return f;
}

function normKey(s) {
  return s.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z]/g, '');
}

// read all pages
const pages = new Map(); // filename -> {word, tema, sinonimos:[hrefs], analogas:[hrefs]}
for (const f of files) {
  const html = fs.readFileSync(path.join(dir, f), 'utf8');
  const h1 = html.match(/<main><h1>([^<]*)<\/h1>/);
  if (!h1) continue; // index/sobre/contato
  const tema = (html.match(/class="tema">Tema: ([^<]*)</) || [])[1] || '';
  const sec = id => {
    const m = html.match(new RegExp(`<section id="${id}">([\\s\\S]*?)</section>`));
    if (!m) return [];
    return [...m[1].matchAll(/<a href="([^"]+)">([^<]*)<\/a>/g)].map(m => [decodeHref(m[1]), m[2]]);
  };
  pages.set(f.toLowerCase(), { file: f, word: h1[1].trim(), tema, sinonimos: sec('sinonimos'), analogas: sec('analogas') });
}

// resolve redirect stubs (meta refresh) to their target page
const redirectTargets = new Map(); // filename-lc -> filename-lc
for (const f of files) {
  if (pages.has(f.toLowerCase())) continue;
  const html = fs.readFileSync(path.join(dir, f), 'utf8');
  const m = html.match(/url=([^"'>]+)/i);
  if (m) redirectTargets.set(f.toLowerCase(), m[1].trim().toLowerCase());
}
const resolveFile = href => {
  let f = href.toLowerCase();
  const seen = new Set();
  while (!byFile.has(f) && redirectTargets.has(f) && !seen.has(f)) { seen.add(f); f = redirectTargets.get(f); }
  return byFile.has(f) ? byFile.get(f) : null;
};
const byFile = new Map([...pages.values()].map(p => [p.file.toLowerCase(), p]));
const byNorm = new Map([...pages.values()].map(p => [normKey(p.word), p]));

// canonical word per page
const words = {};
const broken = [];
for (const p of pages.values()) {
  const links = { sinonimo: [], analoga: [] };
  for (const [kind, list] of [['sinonimo', p.sinonimos], ['analoga', p.analogas]]) {
    for (const [href] of list) {
      const target = resolveFile(href) || byNorm.get(normKey(href.replace(/\.html$/, '')));
      if (target) {
        if (target !== p) links[kind].push(target.word);
      } else {
        broken.push(p.word + ' -> ' + href);
      }
    }
  }
  words[p.word] = { tema: p.tema, sinonimos: [...new Set(links.sinonimo)], analogas: [...new Set(links.analoga)] };
}

// words.json: word -> array of linked words (neighbors, any type)
const wordsJson = {};
for (const [w, v] of Object.entries(words)) {
  wordsJson[w] = [...v.sinonimos, ...v.analogas].filter(x => x in words);
}
fs.writeFileSync('words.json', JSON.stringify(wordsJson, null, 1), 'utf8');

// distinct unordered pairs
const pairs = new Set();
for (const [w, ns] of Object.entries(wordsJson)) {
  for (const n of ns) {
    const a = w < n ? w : n, b = w < n ? n : w;
    if (a !== b) pairs.add(a + '|' + b);
  }
}

const degrees = Object.entries(wordsJson).map(([w, ns]) => [w, ns.length]).sort((a, b) => b[1] - a[1]);
const meta = { words: Object.keys(wordsJson).length, relations: pairs.size, most_connected: degrees.slice(0, 5) };
fs.writeFileSync('result.json', JSON.stringify(meta, null, 2), 'utf8');
fs.writeFileSync('words_meta.json', JSON.stringify(words, null, 1), 'utf8');
console.log(JSON.stringify(meta));
console.log('broken:', broken.length, broken.slice(0, 20));
console.log('temas:', [...new Set(Object.values(words).map(v => v.tema))].join(', '));


